"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { AdminPanel } from "./admin-panel";
import type { DashboardData, PulseFill, WalletRow } from "@/lib/hyperliquid";
import { activityKind, displayCoin, tradeFills, type MarketTrade } from "@/lib/live";
import { findConfluences } from "@/lib/stats";
import {
  defaultActivityFilters, defaultWalletFilters, fillsCsv, filterActivity, filterWallets,
  qualityBand, walletInsights, walletRiskFlags, walletsCsv,
  type ActivityFilters, type WalletFilters, type WalletSort,
} from "@/lib/workspace";

type Tab = "overview" | "wallets" | "pulse" | "favorites" | "admin";
type IconName = "home" | "pulse" | "wallet" | "star" | "search" | "arrow" | "refresh" | "shield" | "settings" | "copy" | "download" | "filter" | "close" | "command" | "eye";
type SessionState = { user: { id: string; firstName: string; lastName: string; username: string }; isAdmin: boolean; initData: string };
type TapeItem = { id: string; coin: string; action: string; kind: "gain" | "loss" | "neutral"; wallet: string; walletName: string; notional: number; price: number; time: number };
type Preset = { id: string; name: string; filters: WalletFilters; sort: WalletSort; direction: "asc" | "desc" };
type SavedWorkspace = { favorites?: string[]; notes?: Record<string, string>; tags?: Record<string, string>; recent?: string[]; presets?: Preset[]; density?: "compact" | "comfortable"; privacy?: boolean; compactNumbers?: boolean; absoluteTime?: boolean; tickerPaused?: boolean; hiddenMarkets?: string[]; signalThreshold?: number; confluenceMinutes?: number };
type NavItem = { id: Tab; label: string; mobileLabel?: string; icon: IconName };

declare global { interface Window { Telegram?: { WebApp?: { initData?: string; ready(): void; expand(): void; version?: string; setHeaderColor(color: string): void; setBackgroundColor(color: string): void } } } }

const nav: NavItem[] = [
  { id: "overview", label: "Главная", icon: "home" },
  { id: "wallets", label: "Трейдеры", mobileLabel: "Топ", icon: "wallet" },
  { id: "pulse", label: "Активность", mobileLabel: "Лента", icon: "pulse" },
  { id: "favorites", label: "Избранное", mobileLabel: "Мои", icon: "star" },
];
const adminNav: NavItem = { id: "admin", label: "Админ", icon: "shield" };
const WORKSPACE_KEY = "dc-pulse-workspace-v2";
const short = (address: string) => `${address.slice(0, 6)}…${address.slice(-4)}`;
const rawMoney = (value: number, compact = true) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", notation: compact ? "compact" : "standard", maximumFractionDigits: compact ? 1 : 2 }).format(value);
const price = (value: number) => value >= 1000 ? `$${value.toLocaleString("en-US", { maximumFractionDigits: 0 })}` : `$${value.toLocaleString("en-US", { maximumFractionDigits: 4 })}`;
const relativeTime = (time: number) => { const seconds = Math.max(0, Math.round((Date.now() - time) / 1000)); return seconds < 60 ? `${seconds}с` : seconds < 3600 ? `${Math.round(seconds / 60)}м` : seconds < 86_400 ? `${Math.round(seconds / 3600)}ч` : `${Math.round(seconds / 86_400)}д`; };
const fillToTape = (fill: PulseFill): TapeItem => { const action = activityKind(fill); return { id: `${fill.hash}:${fill.wallet}:${fill.coin}:${fill.time}`, coin: fill.coin, action: action.label, kind: action.kind, wallet: fill.wallet, walletName: fill.walletName, notional: Number(fill.px) * Number(fill.sz), price: Number(fill.px), time: fill.time }; };
const mergeTape = (current: TapeItem[], incoming: TapeItem[]) => [...incoming, ...current].filter((item, index, rows) => rows.findIndex((row) => row.id === item.id) === index).sort((a, b) => b.time - a.time).slice(0, 600);
const mergeFills = (current: PulseFill[], incoming: PulseFill[]) => {
  const rows = new Map<string, PulseFill>();
  for (const fill of [...current, ...incoming]) {
    const key = `${fill.wallet}:${fill.hash}:${fill.time}:${fill.coin}:${fill.px}:${fill.sz}`;
    const previous = rows.get(key);
    if (!previous || (previous.source === "market" && fill.source !== "market")) rows.set(key, fill);
  }
  return [...rows.values()].sort((a, b) => b.time - a.time).slice(0, 1_000);
};
const download = (name: string, content: string) => { const url = URL.createObjectURL(new Blob([content], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 0); };

export function Dashboard({ initialData }: { initialData: DashboardData }) {
  const [tab, setTab] = useState<Tab>("overview");
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [tags, setTags] = useState<Record<string, string>>({});
  const [recent, setRecent] = useState<string[]>([]);
  const [presets, setPresets] = useState<Preset[]>([]);
  const [walletFilters, setWalletFilters] = useState<WalletFilters>(defaultWalletFilters);
  const [walletSort, setWalletSort] = useState<WalletSort>("rank");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc");
  const [activityFilters, setActivityFilters] = useState<ActivityFilters>(defaultActivityFilters);
  const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [activityLimit, setActivityLimit] = useState(50);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [inspector, setInspector] = useState<WalletRow | null>(null);
  const [compareOpen, setCompareOpen] = useState(false); const [filtersOpen, setFiltersOpen] = useState(false); const [settingsOpen, setSettingsOpen] = useState(false); const [commandOpen, setCommandOpen] = useState(false); const [commandQuery, setCommandQuery] = useState("");
  const [density, setDensity] = useState<"compact" | "comfortable">("compact"); const [privacy, setPrivacy] = useState(false); const [compactNumbers, setCompactNumbers] = useState(true); const [absoluteTime, setAbsoluteTime] = useState(false); const [tickerPaused, setTickerPaused] = useState(false); const [hiddenMarkets, setHiddenMarkets] = useState<Set<string>>(new Set());
  const [signalThreshold, setSignalThreshold] = useState(initialData.config.signalThreshold); const [confluenceMinutes, setConfluenceMinutes] = useState(initialData.config.confluenceMinutes);
  const [fills, setFills] = useState(initialData.fills); const [tape, setTape] = useState(() => mergeTape([], initialData.fills.map(fillToTape))); const [prices, setPrices] = useState(initialData.prices);
  const [live, setLive] = useState(false); const [online, setOnline] = useState(true); const [lastMessage, setLastMessage] = useState(initialData.updatedAt); const [reconnects, setReconnects] = useState(0); const [session, setSession] = useState<SessionState | null>(null); const [toast, setToast] = useState("");

  const saveWorkspace = (patch: Partial<SavedWorkspace>) => { try { const current = JSON.parse(localStorage.getItem(WORKSPACE_KEY) ?? "{}") as SavedWorkspace; localStorage.setItem(WORKSPACE_KEY, JSON.stringify({ ...current, ...patch })); } catch { localStorage.removeItem(WORKSPACE_KEY); } };
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 1800); };
  const copy = async (value: string, message = "Скопировано") => { try { await navigator.clipboard.writeText(value); notify(message); } catch { notify("Не удалось скопировать"); } };
  const formatMoney = (value: number) => privacy ? "••••" : rawMoney(value, compactNumbers);
  const formatTime = (time: number) => absoluteTime ? new Intl.DateTimeFormat("ru-RU", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(time) : relativeTime(time);
  const setPreference = <K extends keyof SavedWorkspace>(key: K, value: SavedWorkspace[K]) => saveWorkspace({ [key]: value });

  useEffect(() => {
    const webApp = window.Telegram?.WebApp; webApp?.ready(); webApp?.expand();
    if (webApp && Number(webApp.version ?? 0) >= 6.1) { webApp.setHeaderColor("#060910"); webApp.setBackgroundColor("#060910"); }
    const telegramData = webApp?.initData ?? "";
    fetch("/api/session", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ initData: telegramData }) }).then((response) => response.ok ? response.json() as Promise<SessionState> : null).then((value) => { if (value) setSession({ ...value, initData: telegramData }); }).catch(() => undefined);
    try {
      const saved = JSON.parse(localStorage.getItem(WORKSPACE_KEY) ?? "{}") as SavedWorkspace;
      queueMicrotask(() => {
        if (Array.isArray(saved.favorites)) setFavorites(new Set(saved.favorites.filter((item): item is string => typeof item === "string")));
        if (saved.notes && typeof saved.notes === "object") setNotes(saved.notes); if (saved.tags && typeof saved.tags === "object") setTags(saved.tags);
        if (Array.isArray(saved.recent)) setRecent(saved.recent.filter((item): item is string => typeof item === "string").slice(0, 8)); if (Array.isArray(saved.presets)) setPresets(saved.presets.filter((item) => item && typeof item.name === "string").slice(0, 8));
        if (saved.density === "compact" || saved.density === "comfortable") setDensity(saved.density); if (typeof saved.privacy === "boolean") setPrivacy(saved.privacy); if (typeof saved.compactNumbers === "boolean") setCompactNumbers(saved.compactNumbers); if (typeof saved.absoluteTime === "boolean") setAbsoluteTime(saved.absoluteTime); if (typeof saved.tickerPaused === "boolean") setTickerPaused(saved.tickerPaused);
        if (Array.isArray(saved.hiddenMarkets)) setHiddenMarkets(new Set(saved.hiddenMarkets)); if (typeof saved.signalThreshold === "number" && saved.signalThreshold >= 0) setSignalThreshold(saved.signalThreshold); if (typeof saved.confluenceMinutes === "number" && saved.confluenceMinutes >= 5) setConfluenceMinutes(saved.confluenceMinutes);
      });
    } catch { localStorage.removeItem(WORKSPACE_KEY); }
    const onOnline = () => setOnline(true); const onOffline = () => setOnline(false); window.addEventListener("online", onOnline); window.addEventListener("offline", onOffline);
    return () => { window.removeEventListener("online", onOnline); window.removeEventListener("offline", onOffline); };
  }, []);

  useEffect(() => { const focusSearch = () => document.querySelector<HTMLInputElement>("#wallet-search")?.focus(); const onKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen((value) => !value); } if (event.key === "/" && !["INPUT", "TEXTAREA", "SELECT"].includes((event.target as HTMLElement).tagName)) { event.preventDefault(); setTab("wallets"); setTimeout(focusSearch, 0); } if (event.key === "Escape") { setCommandOpen(false); setSettingsOpen(false); setCompareOpen(false); setInspector(null); } }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, []);

  useEffect(() => {
    if (!initialData.liveCoins.length) return;
    const names = new Map(initialData.wallets.map((wallet) => [wallet.address.toLowerCase(), wallet.name])); let socket: WebSocket | undefined; let retry: ReturnType<typeof setTimeout> | undefined; let heartbeat: ReturnType<typeof setInterval> | undefined; let stopped = false;
    const connect = () => {
      socket = new WebSocket("wss://api.hyperliquid.xyz/ws");
      socket.onopen = () => { setLive(true); socket?.send(JSON.stringify({ method: "subscribe", subscription: { type: "allMids" } })); for (const wallet of initialData.tracked) socket?.send(JSON.stringify({ method: "subscribe", subscription: { type: "userFills", user: wallet.address, aggregateByTime: true } })); for (const coin of initialData.liveCoins) socket?.send(JSON.stringify({ method: "subscribe", subscription: { type: "trades", coin } })); heartbeat = setInterval(() => socket?.readyState === WebSocket.OPEN && socket.send(JSON.stringify({ method: "ping" })), 45_000); };
      socket.onmessage = ({ data }) => { setLastMessage(Date.now()); try { const message = JSON.parse(data); if (message.channel === "allMids") { const mids = message.data?.mids ?? {}; setPrices((current) => Object.fromEntries(Object.keys(current).map((coin) => [coin, Number(mids[coin] ?? current[coin])]))); } if (message.channel === "userFills") { const payload = message.data; const wallet = String(payload?.user ?? "").toLowerCase(); const incoming = (payload?.fills ?? []).map((fill: PulseFill) => ({ ...fill, coin: displayCoin(fill.coin, initialData.coinNames), wallet, walletName: names.get(wallet) ?? short(wallet), source: "user" as const })); if (incoming.length) { setFills((current) => mergeFills(current, incoming)); setTape((current) => mergeTape(current, incoming.map(fillToTape))); } } if (message.channel === "trades") { const incoming = tradeFills(message.data as MarketTrade[], names, initialData.coinNames); if (incoming.length) { setFills((current) => mergeFills(current, incoming)); setTape((current) => mergeTape(current, incoming.map(fillToTape))); } } } catch { /* malformed transport message */ } };
      socket.onclose = () => { setLive(false); clearInterval(heartbeat); if (!stopped) { setReconnects((value) => value + 1); retry = setTimeout(connect, 3_000); } }; socket.onerror = () => socket?.close();
    };
    connect(); return () => { stopped = true; clearTimeout(retry); clearInterval(heartbeat); socket?.close(); };
  }, [initialData.coinNames, initialData.liveCoins, initialData.tracked, initialData.wallets]);

  const toggleFavorite = (address: string) => setFavorites((current) => { const next = new Set(current); if (next.has(address)) next.delete(address); else next.add(address); saveWorkspace({ favorites: [...next] }); return next; });
  const rememberWallet = (address: string) => setRecent((current) => { const next = [address, ...current.filter((item) => item !== address)].slice(0, 8); saveWorkspace({ recent: next }); return next; });
  const toggleSelected = (address: string) => setSelected((current) => { const next = new Set(current); if (next.has(address)) next.delete(address); else if (next.size < 4) next.add(address); else notify("Можно сравнить до 4 кошельков"); return next; });
  const resetWalletFilters = () => { setWalletFilters(defaultWalletFilters); setWalletSort("rank"); setSortDirection("asc"); setPage(1); };
  const savePreset = () => { const next = [...presets, { id: crypto.randomUUID(), name: `Набор ${presets.length + 1}`, filters: walletFilters, sort: walletSort, direction: sortDirection }].slice(-8); setPresets(next); saveWorkspace({ presets: next }); notify("Набор фильтров сохранён"); };
  const applyPreset = (preset: Preset) => { setWalletFilters(preset.filters); setWalletSort(preset.sort); setSortDirection(preset.direction); setPage(1); }; const removePreset = (id: string) => { const next = presets.filter((item) => item.id !== id); setPresets(next); saveWorkspace({ presets: next }); };

  const filteredWallets = useMemo(() => filterWallets(initialData.wallets, walletFilters, favorites, walletSort, sortDirection), [initialData.wallets, walletFilters, favorites, walletSort, sortDirection]);
  const walletPageCount = Math.max(1, Math.ceil(filteredWallets.length / pageSize)); const safePage = Math.min(page, walletPageCount); const visibleWallets = filteredWallets.slice((safePage - 1) * pageSize, safePage * pageSize);
  const favoriteWallets = initialData.wallets.filter((wallet) => favorites.has(wallet.address)); const comparedWallets = initialData.wallets.filter((wallet) => selected.has(wallet.address)); const recentWallets = recent.map((address) => initialData.wallets.find((wallet) => wallet.address === address)).filter((wallet): wallet is WalletRow => Boolean(wallet));
  const insights = walletInsights(filteredWallets); const filteredFills = useMemo(() => filterActivity(fills, activityFilters, favorites), [fills, activityFilters, favorites]); const coins = [...new Set(fills.map((fill) => fill.coin))].sort(); const confluences = findConfluences(fills, lastMessage, confluenceMinutes * 60_000); const visibleNav = session?.isAdmin ? [...nav, adminNav] : nav;
  const tickerItems = tape.filter((item) => item.notional >= signalThreshold); const activeFilterCount = [walletFilters.performance !== "all", walletFilters.minAccount > 0, walletFilters.minMonthPnl > 0, walletFilters.minRoi > 0, walletFilters.minVolume > 0, walletFilters.namedOnly, walletFilters.favoritesOnly, walletFilters.riskFreeOnly].filter(Boolean).length;
  const fillStats = { long: filteredFills.filter((fill) => /long|buy/i.test(fill.dir)).length, short: filteredFills.filter((fill) => /short|sell/i.test(fill.dir)).length, reduced: filteredFills.filter((fill) => /close|reduce/i.test(fill.dir)).length, wallets: new Set(filteredFills.map((fill) => fill.wallet)).size };
  const commands = [...visibleNav.map((item) => ({ label: `Открыть: ${item.label}`, detail: "Навигация", run: () => setTab(item.id) })), { label: "Найти трейдера", detail: "Поиск", run: () => { setTab("wallets"); setTimeout(() => document.querySelector<HTMLInputElement>("#wallet-search")?.focus(), 0); } }, { label: "Экспортировать рейтинг", detail: "CSV", run: () => download("dc-pulse-wallets.csv", walletsCsv(filteredWallets)) }, { label: privacy ? "Показать суммы" : "Скрыть суммы", detail: "Приватность", run: () => { const next = !privacy; setPrivacy(next); setPreference("privacy", next); } }, { label: "Открыть настройки", detail: "Интерфейс", run: () => setSettingsOpen(true) }].filter((item) => `${item.label} ${item.detail}`.toLowerCase().includes(commandQuery.toLowerCase()));

  return <div className={`min-h-dvh bg-[var(--bg)] pb-20 md:pb-0 density-${density}`}>
    <header className="sticky top-0 z-40 border-b border-[var(--line)] bg-[#060910ed] backdrop-blur-xl"><div className="mx-auto flex h-16 max-w-[1500px] items-center gap-5 px-3 sm:px-5"><button onClick={() => setTab("overview")} aria-label="На главную"><Brand/></button><nav className="hidden h-full items-center gap-1 md:flex" aria-label="Основная навигация">{visibleNav.map((item) => <NavButton key={item.id} item={item} active={tab === item.id} onClick={() => setTab(item.id)}/>)}</nav><div className="ml-auto flex items-center gap-2"><button onClick={() => setCommandOpen(true)} className="command-trigger hidden sm:flex"><Icon name="search" size={14}/><span>Команды</span><kbd>⌘K</kbd></button><button onClick={() => { const next = !privacy; setPrivacy(next); setPreference("privacy", next); }} className="icon-button" aria-label={privacy ? "Показать суммы" : "Скрыть суммы"}><Icon name="eye" size={16}/></button><button onClick={() => setSettingsOpen(true)} className="icon-button" aria-label="Настройки"><Icon name="settings" size={16}/></button><button onClick={() => location.reload()} className="icon-button hidden sm:flex" aria-label="Обновить данные"><Icon name="refresh" size={16}/></button><button onClick={() => setSettingsOpen(true)} className={`status-chip ${live && online ? "text-[var(--cyan)]" : "text-[var(--muted)]"}`} title={`Последнее сообщение: ${formatTime(lastMessage)} · переподключений: ${reconnects}`}><i className={`size-1.5 rounded-full ${live && online ? "live-dot bg-[var(--cyan)]" : "bg-[var(--loss)]"}`}/>{!online ? "OFFLINE" : live ? "LIVE" : "CONNECTING"}</button></div></div></header>
    <ActivityTicker items={tickerItems} paused={tickerPaused} onToggle={() => { const next = !tickerPaused; setTickerPaused(next); setPreference("tickerPaused", next); }} money={formatMoney} time={formatTime} onRemember={rememberWallet}/>
    <main className="mx-auto max-w-[1500px] px-3 py-4 sm:px-5 sm:py-5">
      {initialData.warnings.map((warning) => <div key={warning} className="mb-3 border border-[#ffc4663b] bg-[#ffc4660b] px-3 py-2 text-xs text-[var(--warn)]">{warning}</div>)}
      {tab === "overview" && <Overview initialData={initialData} prices={prices} hiddenMarkets={hiddenMarkets} insights={insights} wallets={initialData.wallets.slice(0, 12)} favorites={favorites} selected={selected} notes={notes} tags={tags} density={density} privacy={privacy} money={formatMoney} time={formatTime} fills={fills} confluences={confluences} confluenceMinutes={confluenceMinutes} recentWallets={recentWallets} onTab={setTab} onCopy={copy} onFavorite={toggleFavorite} onSelect={toggleSelected} onInspect={setInspector} onRemember={rememberWallet} onConfluence={(coin, direction) => { setActivityFilters({ ...defaultActivityFilters, coin, action: direction === "LONG" ? "long" : "short" }); setTab("pulse"); }}/>}
      {tab === "wallets" && <WalletsView wallets={visibleWallets} all={filteredWallets} insights={insights} filters={walletFilters} setFilters={(value) => { setWalletFilters(value); setPage(1); }} sort={walletSort} setSort={(value) => { setWalletSort(value); setPage(1); }} direction={sortDirection} setDirection={setSortDirection} filtersOpen={filtersOpen} setFiltersOpen={setFiltersOpen} activeFilterCount={activeFilterCount} presets={presets} onSavePreset={savePreset} onApplyPreset={applyPreset} onRemovePreset={removePreset} onReset={resetWalletFilters} page={safePage} pages={walletPageCount} pageSize={pageSize} setPage={setPage} setPageSize={(value) => { setPageSize(value); setPage(1); }} favorites={favorites} selected={selected} notes={notes} tags={tags} density={density} privacy={privacy} money={formatMoney} onFavorite={toggleFavorite} onSelect={toggleSelected} onInspect={setInspector} onRemember={rememberWallet} onCopy={copy}/>}
      {tab === "pulse" && <PulseView fills={filteredFills} allFills={fills} filters={activityFilters} setFilters={setActivityFilters} coins={coins} stats={fillStats} live={live} limit={activityLimit} setLimit={setActivityLimit} favorites={favorites} money={formatMoney} time={formatTime} onFavorite={toggleFavorite} onRemember={rememberWallet} onCopy={copy} confluences={confluences} confluenceMinutes={confluenceMinutes}/>}
      {tab === "favorites" && <FavoritesView wallets={favoriteWallets} favorites={favorites} selected={selected} notes={notes} tags={tags} density={density} privacy={privacy} money={formatMoney} onFavorite={toggleFavorite} onSelect={toggleSelected} onInspect={setInspector} onRemember={rememberWallet} onOpen={() => setTab("wallets")}/>}
      {tab === "admin" && session?.isAdmin && <AdminPanel initData={session.initData} liveWallets={initialData.tradeCoverage} exactLiveWallets={initialData.tracked.length} marketCoverage={initialData.liveCoins.length} live={live} events={tape.length} updatedAt={initialData.updatedAt}/>}
    </main>
    {selected.size > 0 && <div className="compare-bar"><div><b>{selected.size} трейдера</b><span className="hidden sm:inline"> выбраны для сравнения</span></div><div className="flex gap-2"><button onClick={() => setSelected(new Set())} className="compact-action">Очистить</button><button onClick={() => setCompareOpen(true)} disabled={selected.size < 2} className="compact-action border border-[#5ee3dc55] bg-[#5ee3dc0b] text-[var(--cyan)] disabled:opacity-40">Сравнить</button></div></div>}
    {settingsOpen && <SettingsDrawer prices={prices} hiddenMarkets={hiddenMarkets} density={density} privacy={privacy} compactNumbers={compactNumbers} absoluteTime={absoluteTime} tickerPaused={tickerPaused} signalThreshold={signalThreshold} confluenceMinutes={confluenceMinutes} live={live} online={online} reconnects={reconnects} lastMessage={lastMessage} time={formatTime} onClose={() => setSettingsOpen(false)} onHiddenMarkets={(next) => { setHiddenMarkets(next); setPreference("hiddenMarkets", [...next]); }} onDensity={(value) => { setDensity(value); setPreference("density", value); }} onPrivacy={(value) => { setPrivacy(value); setPreference("privacy", value); }} onCompactNumbers={(value) => { setCompactNumbers(value); setPreference("compactNumbers", value); }} onAbsoluteTime={(value) => { setAbsoluteTime(value); setPreference("absoluteTime", value); }} onTickerPaused={(value) => { setTickerPaused(value); setPreference("tickerPaused", value); }} onSignalThreshold={(value) => { setSignalThreshold(value); setPreference("signalThreshold", value); }} onConfluenceMinutes={(value) => { setConfluenceMinutes(value); setPreference("confluenceMinutes", value); }}/>}
    {inspector && <WalletInspector wallet={inspector} note={notes[inspector.address] ?? ""} tag={tags[inspector.address] ?? ""} favorite={favorites.has(inspector.address)} money={formatMoney} onFavorite={() => toggleFavorite(inspector.address)} onCopy={copy} onClose={() => setInspector(null)} onSave={(note, tag) => { const nextNotes = { ...notes, [inspector.address]: note }; const nextTags = { ...tags, [inspector.address]: tag }; setNotes(nextNotes); setTags(nextTags); saveWorkspace({ notes: nextNotes, tags: nextTags }); notify("Карточка трейдера сохранена"); }}/>}
    {compareOpen && <CompareDialog wallets={comparedWallets} money={formatMoney} onClose={() => setCompareOpen(false)} onRemove={toggleSelected}/>}
    {commandOpen && <CommandPalette query={commandQuery} setQuery={setCommandQuery} commands={commands} onClose={() => { setCommandOpen(false); setCommandQuery(""); }}/>}
    {toast && <div role="status" className="toast">{toast}</div>}
    <nav className="fixed inset-x-0 bottom-0 z-40 flex border-t border-[var(--line)] bg-[#080c13f5] px-1 pb-[env(safe-area-inset-bottom)] md:hidden" aria-label="Основная навигация">{visibleNav.map((item) => <NavButton key={item.id} item={item} active={tab === item.id} onClick={() => setTab(item.id)}/>)}</nav>
  </div>;
}

function Overview(p: { initialData: DashboardData; prices: Record<string, number>; hiddenMarkets: Set<string>; insights: ReturnType<typeof walletInsights>; wallets: WalletRow[]; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; time(value: number): string; fills: PulseFill[]; confluences: ReturnType<typeof findConfluences>; confluenceMinutes: number; recentWallets: WalletRow[]; onTab(value: Tab): void; onCopy(value: string, message?: string): void; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void; onConfluence(coin: string, direction: string): void }) { return <><div className="mb-4 flex flex-wrap items-end justify-between gap-3"><div><h1 className="text-xl font-semibold tracking-[-.025em] sm:text-2xl">Радар сильных трейдеров</h1><p className="mt-1 text-xs text-[var(--muted)]">{p.initialData.wallets.length} отобраны из {p.initialData.sourceCount.toLocaleString("ru-RU")} публичных аккаунтов</p></div><div className="flex gap-2"><button onClick={() => p.onTab("pulse")} className="compact-action border border-[var(--line)]"><Icon name="pulse" size={14}/>Live-лента</button><button onClick={() => p.onTab("wallets")} className="compact-action border border-[#5ee3dc44] text-[var(--cyan)]">Открыть рейтинг<Icon name="arrow" size={13}/></button></div></div><MarketStrip prices={p.prices} hidden={p.hiddenMarkets} onCopy={(coin, value) => p.onCopy(`${coin} ${price(value)}`, `${coin}: цена скопирована`)}/><section className="mt-4 grid grid-cols-2 overflow-hidden rounded-[10px] border border-[var(--line)] bg-[var(--panel)] sm:grid-cols-3 xl:grid-cols-6"><MetricCard label="Капитал выборки" value={p.money(p.insights.accountValue)}/><MetricCard label="30D PnL" value={p.money(p.insights.monthPnl)} tone={p.insights.monthPnl >= 0 ? "gain" : "loss"}/><MetricCard label="24H PnL" value={p.money(p.insights.dayPnl)} tone={p.insights.dayPnl >= 0 ? "gain" : "loss"}/><MetricCard label="Медиана ROI" value={`${p.insights.medianRoi.toFixed(1)}%`}/><MetricCard label="В плюсе 24H" value={`${p.insights.positiveToday}/${p.initialData.wallets.length}`}/><MetricCard label="Risk alerts" value={String(p.insights.riskFlags)} tone={p.insights.riskFlags ? "warn" : "gain"}/></section><div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_340px]"><section className="surface min-w-0 overflow-hidden"><PanelHead title="Топ трейдеров" note={`${p.initialData.wallets.length} проверяемых аккаунтов`} action="Открыть рейтинг" onAction={() => p.onTab("wallets")}/><TraderTable {...p} onFavorite={p.onFavorite}/></section><aside className="space-y-4"><section className="surface overflow-hidden"><PanelHead title="Совпадения" note={`Одно направление · ${p.confluenceMinutes} минут`}/>{p.confluences.length ? <div>{p.confluences.slice(0, 6).map((item) => <button onClick={() => p.onConfluence(item.coin, item.direction)} key={`${item.coin}-${item.direction}`} className="flex w-full items-center gap-3 border-b border-[var(--line)] px-4 py-3 text-left last:border-0 hover:bg-white/[.025]"><span className={`side-badge ${item.direction === "LONG" ? "gain" : "loss"}`}>{item.direction}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{item.coin}</p><p suppressHydrationWarning className="mt-0.5 truncate text-[11px] text-[var(--muted)]">{item.wallets.length} кошелька · {p.time(item.latest)}</p></div><span className="mono text-xs text-[var(--cyan)]">×{item.wallets.length}</span></button>)}</div> : <Empty text="Свежих совпадений пока нет."/>}</section><section className="surface overflow-hidden"><PanelHead title="Недавно просмотренные" note={`${p.recentWallets.length} на этом устройстве`}/>{p.recentWallets.length ? <MiniWalletList wallets={p.recentWallets} money={p.money} onRemember={p.onRemember}/> : <Empty text="Открой профиль трейдера — он появится здесь."/>}</section><section className="surface overflow-hidden"><PanelHead title="Последняя активность" note={`${p.initialData.tradeCoverage} кошельков live · ${p.initialData.tracked.length} exact`} action="Вся лента" onAction={() => p.onTab("pulse")}/><FillFeed fills={p.fills.slice(0, 7)} favorites={p.favorites} money={p.money} time={p.time} onFavorite={p.onFavorite} onRemember={p.onRemember} onCopy={p.onCopy}/></section></aside></div></>; }

function WalletsView(p: { wallets: WalletRow[]; all: WalletRow[]; insights: ReturnType<typeof walletInsights>; filters: WalletFilters; setFilters(value: WalletFilters): void; sort: WalletSort; setSort(value: WalletSort): void; direction: "asc" | "desc"; setDirection(value: "asc" | "desc"): void; filtersOpen: boolean; setFiltersOpen(value: boolean): void; activeFilterCount: number; presets: Preset[]; onSavePreset(): void; onApplyPreset(preset: Preset): void; onRemovePreset(id: string): void; onReset(): void; page: number; pages: number; pageSize: number; setPage(value: number): void; setPageSize(value: number): void; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void; onCopy(value: string, message?: string): void }) { return <section className="surface overflow-hidden"><div className="flex flex-col gap-3 border-b border-[var(--line)] p-3 sm:p-4"><div className="flex flex-wrap items-end gap-3"><div className="mr-auto"><h1 className="text-lg font-semibold">Рейтинг трейдеров</h1><p className="mt-1 text-[11px] text-[var(--muted)]">Целостные аккаунты: капитал, стабильность, результат и активность</p></div><button onClick={() => download("dc-pulse-wallets.csv", walletsCsv(p.all))} className="compact-action border border-[var(--line)]"><Icon name="download" size={14}/>CSV</button><button onClick={() => p.onCopy(p.all.map((wallet) => wallet.address).join("\n"), "Адреса скопированы")} className="compact-action border border-[var(--line)]"><Icon name="copy" size={14}/>Адреса</button></div><div className="grid gap-2 lg:grid-cols-[minmax(220px,1fr)_150px_110px_auto_auto]"><label className="control-field flex min-w-0 items-center gap-2"><Icon name="search" size={15}/><input id="wallet-search" value={p.filters.query} onChange={(event) => p.setFilters({ ...p.filters, query: event.target.value })} placeholder="Адрес или имя  /" className="min-w-0 flex-1 bg-transparent outline-none"/></label><select value={p.sort} onChange={(event) => p.setSort(event.target.value as WalletSort)} className="control-field" aria-label="Сортировка"><option value="rank">Качество</option><option value="monthPnl">30D PnL</option><option value="monthRoi">30D ROI</option><option value="dayPnl">24H PnL</option><option value="accountValue">Account</option><option value="dayVolume">24H volume</option></select><button onClick={() => p.setDirection(p.direction === "asc" ? "desc" : "asc")} className="control-field flex items-center justify-between">{p.direction === "asc" ? "По возр." : "По убыв."}<span className="mono">{p.direction === "asc" ? "↑" : "↓"}</span></button><button onClick={() => p.setFiltersOpen(!p.filtersOpen)} className={`control-field flex items-center justify-center gap-2 ${p.filtersOpen || p.activeFilterCount ? "border-[#5ee3dc55] text-[var(--cyan)]" : ""}`}><Icon name="filter" size={14}/>Фильтры{p.activeFilterCount ? <b className="filter-count">{p.activeFilterCount}</b> : null}</button><button onClick={p.onReset} className="control-field text-[var(--muted)]">Сбросить</button></div></div>{p.filtersOpen && <WalletFilterPanel filters={p.filters} setFilters={p.setFilters} presets={p.presets} onSavePreset={p.onSavePreset} onApplyPreset={p.onApplyPreset} onRemovePreset={p.onRemovePreset}/>}<div className="flex flex-wrap items-center gap-x-4 gap-y-2 border-b border-[var(--line)] bg-white/[.012] px-4 py-2 text-[10px] text-[var(--muted)]"><span><b className="mono text-white">{p.all.length}</b> найдено</span><span>Капитал <b className="mono text-white">{p.money(p.insights.accountValue)}</b></span><span>30D <b className={`mono ${p.insights.monthPnl >= 0 ? "text-[var(--cyan)]" : "text-[var(--loss)]"}`}>{p.money(p.insights.monthPnl)}</b></span><span className="ml-auto">Выбрано <b className="mono text-white">{p.selected.size}/4</b></span></div>{p.wallets.length ? <TraderTable {...p} onFavorite={p.onFavorite}/> : <EmptyState title="Ничего не найдено" text="Ослабь фильтры или сбрось поиск." action="Сбросить фильтры" onAction={p.onReset}/>}<Pagination page={p.page} pages={p.pages} pageSize={p.pageSize} total={p.all.length} onPage={p.setPage} onPageSize={p.setPageSize}/></section>; }

function PulseView(p: { fills: PulseFill[]; allFills: PulseFill[]; filters: ActivityFilters; setFilters(value: ActivityFilters): void; coins: string[]; stats: { long: number; short: number; reduced: number; wallets: number }; live: boolean; limit: number; setLimit(value: number): void; favorites: Set<string>; money(value: number): string; time(value: number): string; onFavorite(address: string): void; onRemember(address: string): void; onCopy(value: string, message?: string): void; confluences: ReturnType<typeof findConfluences>; confluenceMinutes: number }) { return <div className="space-y-4"><section className="surface overflow-hidden"><PanelHead title="Живая активность" note={`${p.live ? "WebSocket подключён" : "Переподключение"} · BUY/SELL для всей базы, точные Open/Close для exact`} action="Экспорт CSV" onAction={() => download("dc-pulse-activity.csv", fillsCsv(p.fills))}/><div className="grid grid-cols-2 border-b border-[var(--line)] sm:grid-cols-4"><Summary label="Long / Buy" value={String(p.stats.long)} accent/><Summary label="Short / Sell" value={String(p.stats.short)}/><Summary label="Сокращения" value={String(p.stats.reduced)}/><Summary label="Кошельки" value={String(p.stats.wallets)}/></div><ActivityToolbar filters={p.filters} coins={p.coins} setFilters={p.setFilters}/>{p.fills.length ? <FillFeed fills={p.fills.slice(0, p.limit)} favorites={p.favorites} money={p.money} time={p.time} onFavorite={p.onFavorite} onRemember={p.onRemember} onCopy={p.onCopy}/> : <EmptyState title="Сделок нет" text="Попробуй другой рынок, размер или направление." action="Сбросить фильтры" onAction={() => p.setFilters(defaultActivityFilters)}/>} {p.fills.length > p.limit && <div className="border-t border-[var(--line)] p-3 text-center"><button onClick={() => p.setLimit(p.limit + 50)} className="compact-action border border-[var(--line)]">Показать ещё 50</button></div>}</section><section className="surface overflow-hidden"><PanelHead title="Совпадения кошельков" note={`Одно направление за ${p.confluenceMinutes} минут`}/>{p.confluences.length ? <div className="grid sm:grid-cols-2 xl:grid-cols-3">{p.confluences.map((item) => <button key={`${item.coin}-${item.direction}`} onClick={() => p.setFilters({ ...defaultActivityFilters, coin: item.coin, action: item.direction === "LONG" ? "long" : "short" })} className="flex items-center gap-3 border-b border-r border-[var(--line)] px-4 py-3 text-left hover:bg-white/[.025]"><span className={`side-badge ${item.direction === "LONG" ? "gain" : "loss"}`}>{item.direction}</span><div className="flex-1"><p className="font-semibold">{item.coin}</p><p className="text-[10px] text-[var(--muted)]">{item.wallets.length} кошелька</p></div><span className="mono text-[var(--cyan)]">×{item.wallets.length}</span></button>)}</div> : <Empty text="Сейчас нет подтверждённых совпадений."/>}</section></div>; }

function FavoritesView(p: { wallets: WalletRow[]; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void; onOpen(): void }) { const insights = walletInsights(p.wallets); return <section className="surface overflow-hidden"><PanelHead title="Избранные трейдеры" note={`${p.wallets.length} сохранено локально`} action={p.wallets.length ? "Экспорт CSV" : undefined} onAction={() => download("dc-pulse-favorites.csv", walletsCsv(p.wallets))}/>{p.wallets.length ? <><div className="grid grid-cols-2 border-b border-[var(--line)] sm:grid-cols-4"><Summary label="Account value" value={p.money(insights.accountValue)}/><Summary label="30D PnL" value={p.money(insights.monthPnl)} accent/><Summary label="В плюсе 24H" value={String(insights.positiveToday)}/><Summary label="С заметками" value={String(p.wallets.filter((wallet) => p.notes[wallet.address]).length)}/></div><TraderTable {...p} onFavorite={p.onFavorite}/></> : <EmptyState title="Избранное пусто" text="Нажми звезду у трейдера — профиль останется под рукой." action="Открыть рейтинг" onAction={p.onOpen}/>}</section>; }

function Brand() { return <span className="flex shrink-0 items-center gap-2.5 text-left"><span className="relative size-9 overflow-hidden rounded-[9px] border border-white/[.08] bg-[#02060c]"><Image src="/dc-pulse-mark.png" fill sizes="36px" alt="" className="object-cover" priority/></span><span className="block text-sm font-semibold leading-none">Deep Current</span></span>; }
function ActivityTicker({ items, paused, onToggle, money, time, onRemember }: { items: TapeItem[]; paused: boolean; onToggle(): void; money(value: number): string; time(value: number): string; onRemember(address: string): void }) { return <section className="border-b border-[var(--line)] bg-[#080c13]"><div className="mx-auto flex h-11 max-w-[1800px] items-stretch"><button onClick={onToggle} className="ticker-toggle" aria-label={paused ? "Запустить ленту" : "Приостановить ленту"}>{paused ? "▶" : "Ⅱ"}</button><div className="flex min-w-0 flex-1 items-stretch overflow-x-auto thin-scrollbar">{items.length ? items.slice(0, 24).map((item) => <Link onClick={() => onRemember(item.wallet)} href={`/wallet/${item.wallet}`} key={item.id} className="flex shrink-0 items-center gap-2 border-r border-[var(--line)] px-3 text-[10px] hover:bg-white/[.025]"><span className="mono flex size-5 items-center justify-center rounded-full border border-white/[.1] bg-white/[.035] text-[8px]">{item.coin.slice(0, 2)}</span><b className="text-xs">{item.coin}</b><span className={`side-badge !h-[19px] !min-w-0 px-2 ${item.kind === "gain" ? "gain" : item.kind === "loss" ? "loss" : ""}`}>{item.action}</span><span className="mono text-[var(--muted)]">{short(item.wallet)}</span><strong className="mono text-[11px]">{money(item.notional)}</strong><time suppressHydrationWarning className="mono text-[var(--muted)]">{time(item.time)}</time></Link>) : <p className="flex items-center px-4 text-[10px] text-[var(--muted)]">Ожидаем крупную сделку…</p>}</div></div></section>; }
function MarketStrip({ prices, hidden, onCopy }: { prices: Record<string, number>; hidden: Set<string>; onCopy(coin: string, value: number): void }) { const visible = Object.entries(prices).filter(([coin]) => !hidden.has(coin)); return <section className="surface flex min-h-14 items-stretch overflow-x-auto thin-scrollbar">{visible.length ? visible.map(([coin, value], index) => <button onClick={() => onCopy(coin, value)} key={coin} className={`flex min-w-[150px] flex-1 items-center justify-between gap-4 px-4 py-2 text-left hover:bg-white/[.025] ${index ? "border-l border-[var(--line)]" : ""}`}><span><span className="block text-[10px] text-[var(--muted)]">{coin} / USD</span><span className="mono mt-1 block text-sm">{value ? price(value) : "—"}</span></span><span className="size-1.5 rounded-full bg-[var(--cyan)]"/></button>) : <p className="flex items-center px-4 text-xs text-[var(--muted)]">Все рынки скрыты.</p>}</section>; }

function TraderTable({ wallets, favorites, selected, notes, tags, density, privacy, money, onFavorite, onSelect, onInspect, onRemember }: { wallets: WalletRow[]; favorites: Set<string>; selected: Set<string>; notes: Record<string, string>; tags: Record<string, string>; density: "compact" | "comfortable"; privacy: boolean; money(value: number): string; onFavorite(address: string): void; onSelect(address: string): void; onInspect(wallet: WalletRow): void; onRemember(address: string): void }) { return <div><div className="hidden grid-cols-[42px_minmax(190px,1fr)_120px_110px_120px_90px_120px_80px] items-center border-b border-[var(--line)] px-3 py-2 text-[9px] font-semibold uppercase tracking-[.08em] text-[var(--muted)] lg:grid"><span>#</span><span>Trader</span><span className="text-right">Account</span><span className="text-right">24H PnL</span><span className="text-right">30D PnL</span><span className="text-right">30D ROI</span><span className="text-right">24H volume</span><span/></div><div className="divide-y divide-[var(--line)]">{wallets.map((wallet) => { const risks = walletRiskFlags(wallet); return <article key={wallet.address} className={`group relative grid grid-cols-2 gap-x-3 px-3 hover:bg-white/[.025] sm:grid-cols-5 lg:grid-cols-[42px_minmax(190px,1fr)_120px_110px_120px_90px_120px_80px] lg:items-center ${density === "comfortable" ? "py-4 lg:py-3.5" : "py-3 lg:py-2.5"} ${selected.has(wallet.address) ? "bg-[#5ee3dc08]" : ""}`}><button onClick={() => onSelect(wallet.address)} className={`mono hidden size-7 items-center justify-center rounded-md border text-[10px] lg:flex ${selected.has(wallet.address) ? "border-[#5ee3dc66] bg-[#5ee3dc12] text-[var(--cyan)]" : "border-transparent text-[var(--muted)]"}`}>{selected.has(wallet.address) ? "✓" : String(wallet.rank).padStart(2, "0")}</button><div className="col-span-2 flex min-w-0 items-center gap-3 sm:col-span-5 lg:col-span-1"><button onClick={() => onSelect(wallet.address)} className={`mono flex size-8 shrink-0 items-center justify-center rounded-full border text-[10px] lg:hidden ${selected.has(wallet.address) ? "border-[#5ee3dc66] text-[var(--cyan)]" : "border-white/[.08]"}`}>{selected.has(wallet.address) ? "✓" : wallet.rank}</button><Link onClick={() => onRemember(wallet.address)} href={`/wallet/${wallet.address}`} className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-sm font-medium group-hover:text-[var(--cyan)]">{wallet.name}</p><span className={`quality-badge quality-${qualityBand(wallet).toLowerCase()}`}>{qualityBand(wallet)}</span>{risks.length ? <span title={risks.join(" · ")} className="risk-dot">!</span> : null}</div><p className="mono mt-0.5 text-[10px] text-[var(--muted)]">{privacy ? "0x••••••••••" : short(wallet.address)}{tags[wallet.address] ? ` · ${tags[wallet.address]}` : ""}{notes[wallet.address] ? " · 📝" : ""}</p></Link></div><Cell label="Account" value={money(wallet.accountValue)}/><Cell label="24H PnL" value={<Pnl value={wallet.dayPnl} money={money}/>}/><Cell label="30D PnL" value={<Pnl value={wallet.monthPnl} money={money}/>}/><Cell label="30D ROI" value={<Pnl value={wallet.monthRoi} suffix="%" money={money}/>}/><Cell label="24H volume" value={money(wallet.dayVolume)}/><div className="absolute right-3 top-3 flex gap-1 lg:static lg:justify-end"><button onClick={() => onInspect(wallet)} className="icon-button" aria-label="Карточка трейдера"><Icon name="command" size={14}/></button><button onClick={() => onFavorite(wallet.address)} className="icon-button" aria-label="Избранное"><Icon name="star" size={15} filled={favorites.has(wallet.address)}/></button></div></article>; })}</div></div>; }

function WalletFilterPanel({ filters, setFilters, presets, onSavePreset, onApplyPreset, onRemovePreset }: { filters: WalletFilters; setFilters(value: WalletFilters): void; presets: Preset[]; onSavePreset(): void; onApplyPreset(preset: Preset): void; onRemovePreset(id: string): void }) { return <div className="border-b border-[var(--line)] bg-[#080d15] p-4"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><FilterSelect label="Результат 24H" value={filters.performance} onChange={(value) => setFilters({ ...filters, performance: value as WalletFilters["performance"] })} options={[["all", "Все"], ["winners", "Только в плюсе"], ["losers", "Только в минусе"]]}/><NumberFilter label="Мин. капитал" value={filters.minAccount} onChange={(value) => setFilters({ ...filters, minAccount: value })}/><NumberFilter label="Мин. 30D PnL" value={filters.minMonthPnl} onChange={(value) => setFilters({ ...filters, minMonthPnl: value })}/><NumberFilter label="Мин. 30D ROI, %" value={filters.minRoi} onChange={(value) => setFilters({ ...filters, minRoi: value })}/><NumberFilter label="Мин. объём 24H" value={filters.minVolume} onChange={(value) => setFilters({ ...filters, minVolume: value })}/><Toggle label="Только с именем" checked={filters.namedOnly} onChange={(value) => setFilters({ ...filters, namedOnly: value })}/><Toggle label="Только избранные" checked={filters.favoritesOnly} onChange={(value) => setFilters({ ...filters, favoritesOnly: value })}/><Toggle label="Без risk-флагов" checked={filters.riskFreeOnly} onChange={(value) => setFilters({ ...filters, riskFreeOnly: value })}/></div><div className="mt-4 flex flex-wrap items-center gap-2 border-t border-[var(--line)] pt-3"><button onClick={onSavePreset} className="compact-action border border-[var(--line)]">+ Сохранить набор</button>{presets.map((preset) => <span key={preset.id} className="preset-chip"><button onClick={() => onApplyPreset(preset)}>{preset.name}</button><button onClick={() => onRemovePreset(preset.id)} aria-label={`Удалить ${preset.name}`}>×</button></span>)}</div></div>; }
function ActivityToolbar({ filters, coins, setFilters }: { filters: ActivityFilters; coins: string[]; setFilters(value: ActivityFilters): void }) { return <div className="grid gap-2 border-b border-[var(--line)] p-3 sm:grid-cols-2 lg:grid-cols-[minmax(180px,1fr)_130px_130px_140px_130px_auto]"><label className="control-field flex items-center gap-2"><Icon name="search" size={14}/><input value={filters.query} onChange={(event) => setFilters({ ...filters, query: event.target.value })} placeholder="Монета, имя или адрес" className="min-w-0 flex-1 bg-transparent outline-none"/></label><select value={filters.coin} onChange={(event) => setFilters({ ...filters, coin: event.target.value })} className="control-field"><option value="all">Все рынки</option>{coins.map((coin) => <option key={coin}>{coin}</option>)}</select><select value={filters.action} onChange={(event) => setFilters({ ...filters, action: event.target.value as ActivityFilters["action"] })} className="control-field"><option value="all">Все действия</option><option value="long">Long</option><option value="short">Short</option><option value="reduced">Сокращения</option></select><select value={filters.minNotional} onChange={(event) => setFilters({ ...filters, minNotional: Number(event.target.value) })} className="control-field"><option value="0">Любой размер</option><option value="5000">От $5K</option><option value="25000">От $25K</option><option value="100000">От $100K</option><option value="500000">От $500K</option></select><select value={filters.sort} onChange={(event) => setFilters({ ...filters, sort: event.target.value as ActivityFilters["sort"] })} className="control-field"><option value="newest">Сначала новые</option><option value="largest">Сначала крупные</option></select><Toggle label="Избранные" checked={filters.favoritesOnly} onChange={(value) => setFilters({ ...filters, favoritesOnly: value })}/></div>; }
function FillFeed({ fills, favorites, money, time, onFavorite, onRemember, onCopy }: { fills: PulseFill[]; favorites: Set<string>; money(value: number): string; time(value: number): string; onFavorite(address: string): void; onRemember(address: string): void; onCopy(value: string, message?: string): void }) { if (!fills.length) return <Empty text="Новые сделки появятся здесь автоматически."/>; return <div className="divide-y divide-[var(--line)]">{fills.map((fill, index) => { const action = activityKind(fill); const notional = Number(fill.sz) * Number(fill.px); return <article key={`${fill.hash}-${fill.wallet}-${index}`} className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 px-4 py-2.5 hover:bg-white/[.025]"><span className={`side-badge ${action.kind === "neutral" ? "" : action.kind}`}>{action.label}</span><Link onClick={() => onRemember(fill.wallet)} href={`/wallet/${fill.wallet}`} className="min-w-0"><p className="truncate text-xs font-medium"><b className="mr-1.5">{fill.coin}</b><span className="font-normal text-[var(--muted)]">{fill.walletName}</span></p><p className="mono mt-0.5 truncate text-[10px] text-[var(--muted)]">{Number(fill.sz).toLocaleString("en-US", { maximumFractionDigits: 4 })} @ {price(Number(fill.px))} · {money(notional)} · <time suppressHydrationWarning>{time(fill.time)}</time></p></Link><div className="flex items-center gap-1"><button onClick={() => onCopy(`${fill.wallet} ${fill.coin} ${fill.dir} ${notional}`, "Событие скопировано")} className="icon-button"><Icon name="copy" size={13}/></button><button onClick={() => onFavorite(fill.wallet)} className="icon-button"><Icon name="star" size={13} filled={favorites.has(fill.wallet)}/></button></div></article>; })}</div>; }
function MiniWalletList({ wallets, money, onRemember }: { wallets: WalletRow[]; money(value: number): string; onRemember(address: string): void }) { return <div className="divide-y divide-[var(--line)]">{wallets.map((wallet) => <Link onClick={() => onRemember(wallet.address)} href={`/wallet/${wallet.address}`} key={wallet.address} className="flex items-center gap-3 px-4 py-2.5 hover:bg-white/[.025]"><span className="mono flex size-7 items-center justify-center rounded-full bg-white/[.035] text-[9px] text-[var(--cyan)]">{wallet.rank}</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-medium">{wallet.name}</span><span className="mono text-[9px] text-[var(--muted)]">{short(wallet.address)}</span></span><Pnl value={wallet.monthPnl} money={money}/></Link>)}</div>; }
function Pagination({ page, pages, pageSize, total, onPage, onPageSize }: { page: number; pages: number; pageSize: number; total: number; onPage(value: number): void; onPageSize(value: number): void }) { return <div className="flex flex-wrap items-center gap-3 border-t border-[var(--line)] px-4 py-3 text-[10px] text-[var(--muted)]"><span>{total ? (page - 1) * pageSize + 1 : 0}–{Math.min(page * pageSize, total)} из {total}</span><label className="ml-auto flex items-center gap-2">Строк<select value={pageSize} onChange={(event) => onPageSize(Number(event.target.value))} className="control-field !min-h-8"><option value="10">10</option><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label><button disabled={page <= 1} onClick={() => onPage(page - 1)} className="pagination-button">←</button><span className="mono text-white">{page}/{pages}</span><button disabled={page >= pages} onClick={() => onPage(page + 1)} className="pagination-button">→</button></div>; }

function SettingsDrawer(p: { prices: Record<string, number>; hiddenMarkets: Set<string>; density: "compact" | "comfortable"; privacy: boolean; compactNumbers: boolean; absoluteTime: boolean; tickerPaused: boolean; signalThreshold: number; confluenceMinutes: number; live: boolean; online: boolean; reconnects: number; lastMessage: number; time(value: number): string; onClose(): void; onHiddenMarkets(value: Set<string>): void; onDensity(value: "compact" | "comfortable"): void; onPrivacy(value: boolean): void; onCompactNumbers(value: boolean): void; onAbsoluteTime(value: boolean): void; onTickerPaused(value: boolean): void; onSignalThreshold(value: number): void; onConfluenceMinutes(value: number): void }) { return <Drawer title="Настройки пространства" note="Сохраняются на этом устройстве" onClose={p.onClose}><div className="space-y-5"><SettingGroup title="Интерфейс"><Segmented value={p.density} options={[["compact", "Компактно"], ["comfortable", "Свободно"]]} onChange={(value) => p.onDensity(value as typeof p.density)}/><Toggle label="Скрывать денежные суммы" checked={p.privacy} onChange={p.onPrivacy}/><Toggle label="Сокращать большие числа" checked={p.compactNumbers} onChange={p.onCompactNumbers}/><Toggle label="Абсолютное время событий" checked={p.absoluteTime} onChange={p.onAbsoluteTime}/><Toggle label="Приостановить верхнюю ленту" checked={p.tickerPaused} onChange={p.onTickerPaused}/></SettingGroup><SettingGroup title="Сигналы"><FilterSelect label="Минимальный размер" value={String(p.signalThreshold)} onChange={(value) => p.onSignalThreshold(Number(value))} options={[["1000", "$1K"], ["5000", "$5K"], ["10000", "$10K"], ["25000", "$25K"], ["100000", "$100K"]]}/><FilterSelect label="Окно совпадения" value={String(p.confluenceMinutes)} onChange={(value) => p.onConfluenceMinutes(Number(value))} options={[["5", "5 минут"], ["15", "15 минут"], ["30", "30 минут"], ["60", "60 минут"], ["120", "120 минут"]]}/></SettingGroup><SettingGroup title="Рынки на главной"><div className="flex flex-wrap gap-2">{Object.keys(p.prices).map((coin) => <button key={coin} onClick={() => { const next = new Set(p.hiddenMarkets); if (next.has(coin)) next.delete(coin); else next.add(coin); p.onHiddenMarkets(next); }} className={`market-toggle ${p.hiddenMarkets.has(coin) ? "opacity-45" : "active"}`}>{coin}</button>)}</div></SettingGroup><SettingGroup title="Диагностика"><dl className="space-y-3"><Detail label="Интернет" value={p.online ? "Онлайн" : "Офлайн"}/><Detail label="WebSocket" value={p.live ? "Подключён" : "Переподключение"}/><Detail label="Последнее событие" value={p.time(p.lastMessage)}/><Detail label="Переподключения" value={String(p.reconnects)}/></dl></SettingGroup></div></Drawer>; }
function WalletInspector({ wallet, note, tag, favorite, money, onFavorite, onCopy, onClose, onSave }: { wallet: WalletRow; note: string; tag: string; favorite: boolean; money(value: number): string; onFavorite(): void; onCopy(value: string, message?: string): void; onClose(): void; onSave(note: string, tag: string): void }) { const [draftNote, setDraftNote] = useState(note); const [draftTag, setDraftTag] = useState(tag); return <Drawer title={wallet.name} note={short(wallet.address)} onClose={onClose}><div className="space-y-5"><div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-[var(--line)] bg-[var(--line)]"><MetricCard label="Account" value={money(wallet.accountValue)}/><MetricCard label="30D PnL" value={money(wallet.monthPnl)} tone={wallet.monthPnl >= 0 ? "gain" : "loss"}/><MetricCard label="30D ROI" value={`${wallet.monthRoi.toFixed(1)}%`}/><MetricCard label="24H volume" value={money(wallet.dayVolume)}/></div><div><p className="mb-2 text-[10px] uppercase text-[var(--muted)]">Risk flags</p><div className="flex flex-wrap gap-2">{walletRiskFlags(wallet).length ? walletRiskFlags(wallet).map((flag) => <span key={flag} className="risk-chip">{flag}</span>) : <span className="quality-badge quality-elite">Нет флагов</span>}</div></div><label className="block text-[10px] text-[var(--muted)]">Моя метка<input value={draftTag} maxLength={24} onChange={(event) => setDraftTag(event.target.value)} placeholder="Например: скальпер" className="control-field mt-2 w-full"/></label><label className="block text-[10px] text-[var(--muted)]">Личная заметка<textarea value={draftNote} maxLength={500} onChange={(event) => setDraftNote(event.target.value)} placeholder="Что важно помнить" className="control-field mt-2 min-h-28 w-full resize-y py-3"/></label><div className="grid grid-cols-2 gap-2"><button onClick={onFavorite} className="control-field flex items-center justify-center gap-2"><Icon name="star" size={14} filled={favorite}/>{favorite ? "В избранном" : "В избранное"}</button><button onClick={() => onCopy(wallet.address, "Адрес скопирован")} className="control-field flex items-center justify-center gap-2"><Icon name="copy" size={14}/>Адрес</button><Link href={`/wallet/${wallet.address}`} className="control-field col-span-2 flex items-center justify-center gap-2 text-[var(--cyan)]">Открыть профиль<Icon name="arrow" size={13}/></Link><button onClick={() => onSave(draftNote.trim(), draftTag.trim())} className="col-span-2 h-10 rounded-md bg-[var(--cyan)] text-xs font-semibold text-[#041110]">Сохранить карточку</button></div></div></Drawer>; }
function CompareDialog({ wallets, money, onClose, onRemove }: { wallets: WalletRow[]; money(value: number): string; onClose(): void; onRemove(address: string): void }) { const metrics: [string, (wallet: WalletRow) => string][] = [["Account", (w) => money(w.accountValue)], ["24H PnL", (w) => money(w.dayPnl)], ["7D PnL", (w) => money(w.weekPnl)], ["30D PnL", (w) => money(w.monthPnl)], ["30D ROI", (w) => `${w.monthRoi.toFixed(1)}%`], ["24H volume", (w) => money(w.dayVolume)], ["Качество", qualityBand], ["Risk flags", (w) => String(walletRiskFlags(w).length)]]; return <Modal title="Сравнение трейдеров" note="До четырёх аккаунтов рядом" onClose={onClose}><div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-xs"><thead><tr><th className="p-3 text-[var(--muted)]">Метрика</th>{wallets.map((wallet) => <th key={wallet.address} className="p-3"><span className="block max-w-40 truncate">{wallet.name}</span><button onClick={() => onRemove(wallet.address)} className="mt-1 text-[9px] text-[var(--loss)]">Убрать</button></th>)}</tr></thead><tbody>{metrics.map(([label, get]) => <tr key={label} className="border-t border-[var(--line)]"><td className="p-3 text-[var(--muted)]">{label}</td>{wallets.map((wallet) => <td key={wallet.address} className="mono p-3">{get(wallet)}</td>)}</tr>)}</tbody></table></div></Modal>; }
function CommandPalette({ query, setQuery, commands, onClose }: { query: string; setQuery(value: string): void; commands: { label: string; detail: string; run(): void }[]; onClose(): void }) { return <Modal title="Командная строка" note="Навигация и быстрые действия · Esc закрыть" onClose={onClose}><label className="control-field flex items-center gap-2"><Icon name="search" size={15}/><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Введите команду…" className="min-w-0 flex-1 bg-transparent outline-none"/></label><div className="mt-3 divide-y divide-[var(--line)] overflow-hidden rounded-lg border border-[var(--line)]">{commands.length ? commands.map((command) => <button key={command.label} onClick={() => { command.run(); onClose(); }} className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left hover:bg-white/[.035]"><span className="text-xs font-medium">{command.label}</span><span className="text-[10px] text-[var(--muted)]">{command.detail}</span></button>) : <Empty text="Команда не найдена."/>}</div></Modal>; }
function Drawer({ title, note, onClose, children }: { title: string; note: string; onClose(): void; children: React.ReactNode }) { return <div className="overlay" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside role="dialog" aria-modal="true" className="drawer"><DialogHead title={title} note={note} onClose={onClose}/><div className="overflow-y-auto p-4">{children}</div></aside></div>; }
function Modal({ title, note, onClose, children }: { title: string; note: string; onClose(): void; children: React.ReactNode }) { return <div className="overlay items-start justify-center p-3 pt-[8vh]" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section role="dialog" aria-modal="true" className="modal-panel"><DialogHead title={title} note={note} onClose={onClose}/><div className="p-4">{children}</div></section></div>; }
function DialogHead({ title, note, onClose }: { title: string; note: string; onClose(): void }) { return <div className="flex items-center justify-between border-b border-[var(--line)] p-4"><div><h2 className="text-base font-semibold">{title}</h2><p className="mt-1 text-[10px] text-[var(--muted)]">{note}</p></div><button onClick={onClose} className="icon-button"><Icon name="close" size={16}/></button></div>; }

function PanelHead({ title, note, action, onAction }: { title: string; note: string; action?: string; onAction?: () => void }) { return <div className="flex min-h-14 items-center justify-between gap-3 border-b border-[var(--line)] px-4 py-3"><div><h2 className="text-sm font-semibold">{title}</h2><p className="mt-0.5 text-[10px] text-[var(--muted)]">{note}</p></div>{action && onAction && <button onClick={onAction} className="compact-action">{action}<Icon name="arrow" size={13}/></button>}</div>; }
function MetricCard({ label, value, tone }: { label: string; value: string; tone?: "gain" | "loss" | "warn" }) { return <div className="border-b border-r border-[var(--line)] bg-[var(--panel)] px-4 py-3"><p className="text-[9px] uppercase tracking-[.06em] text-[var(--muted)]">{label}</p><p className={`mono mt-1 truncate text-base font-semibold ${tone === "gain" ? "text-[var(--cyan)]" : tone === "loss" ? "text-[var(--loss)]" : tone === "warn" ? "text-[var(--warn)]" : "text-white"}`}>{value}</p></div>; }
function Summary({ label, value, accent = false }: { label: string; value: string; accent?: boolean }) { return <div className="border-r border-[var(--line)] px-3 py-2.5 last:border-r-0 sm:px-4"><p className="text-[9px] uppercase text-[var(--muted)]">{label}</p><p className={`mono mt-1 text-sm font-semibold ${accent ? "text-[var(--cyan)]" : "text-white"}`}>{value}</p></div>; }
function Cell({ label, value }: { label: string; value: React.ReactNode }) { return <div className="mt-3 min-w-0 lg:mt-0 lg:text-right"><p className="text-[9px] uppercase text-[var(--muted)] lg:hidden">{label}</p><div className="mono mt-1 truncate text-xs lg:mt-0">{value}</div></div>; }
function Pnl({ value, suffix = "", money }: { value: number; suffix?: string; money(value: number): string }) { return <span className={value >= 0 ? "text-[var(--cyan)]" : "text-[var(--loss)]"}>{value >= 0 ? "+" : ""}{suffix ? value.toFixed(1) : money(value)}{suffix}</span>; }
function Empty({ text }: { text: string }) { return <p className="px-5 py-12 text-center text-xs text-[var(--muted)]">{text}</p>; }
function EmptyState({ title, text, action, onAction }: { title: string; text: string; action: string; onAction(): void }) { return <div className="px-5 py-16 text-center"><div className="mx-auto flex size-10 items-center justify-center rounded-full border border-[var(--line)] text-[var(--muted)]"><Icon name="search" size={17}/></div><h3 className="mt-3 text-sm font-semibold">{title}</h3><p className="mt-1 text-xs text-[var(--muted)]">{text}</p><button onClick={onAction} className="compact-action mt-4 border border-[var(--line)]">{action}</button></div>; }
function Toggle({ label, checked, onChange }: { label: string; checked: boolean; onChange(value: boolean): void }) { return <label className="flex min-h-9 cursor-pointer items-center justify-between gap-3 rounded-md border border-[var(--line)] bg-[var(--panel-2)] px-3 text-[11px]"><span>{label}</span><input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} className="toggle-input"/></label>; }
function NumberFilter({ label, value, onChange }: { label: string; value: number; onChange(value: number): void }) { return <label className="text-[10px] text-[var(--muted)]">{label}<input type="number" min="0" value={value || ""} onChange={(event) => onChange(Math.max(0, Number(event.target.value)))} placeholder="0" className="control-field mt-2 w-full"/></label>; }
function FilterSelect({ label, value, onChange, options }: { label: string; value: string; onChange(value: string): void; options: string[][] }) { return <label className="text-[10px] text-[var(--muted)]">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="control-field mt-2 w-full">{options.map(([option, text]) => <option key={option} value={option}>{text}</option>)}</select></label>; }
function Segmented({ value, options, onChange }: { value: string; options: string[][]; onChange(value: string): void }) { return <div className="segmented">{options.map(([option, text]) => <button key={option} onClick={() => onChange(option)} className={value === option ? "active" : ""}>{text}</button>)}</div>; }
function SettingGroup({ title, children }: { title: string; children: React.ReactNode }) { return <section><h3 className="mb-3 text-[10px] font-semibold uppercase tracking-[.1em] text-[var(--muted)]">{title}</h3><div className="space-y-2">{children}</div></section>; }
function Detail({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between gap-3"><dt className="text-[11px] text-[var(--muted)]">{label}</dt><dd className="mono text-[11px]">{value}</dd></div>; }
function NavButton({ item, active, onClick }: { item: NavItem; active: boolean; onClick(): void }) { return <button onClick={onClick} aria-current={active ? "page" : undefined} className={`relative flex min-h-14 min-w-0 flex-1 flex-col items-center justify-center gap-1 px-1 text-[9px] font-medium md:min-h-9 md:flex-none md:flex-row md:gap-2 md:rounded-md md:px-3 md:text-xs ${active ? "text-[var(--cyan)] md:bg-[#5ee3dc12]" : "text-[var(--muted)] hover:text-white"}`}><Icon name={item.icon} size={16} filled={item.icon === "star" && active}/><span className="max-w-full truncate md:hidden">{item.mobileLabel ?? item.label}</span><span className="hidden md:inline">{item.label}</span>{active && <i className="absolute inset-x-3 top-0 h-px bg-[var(--cyan)] md:hidden"/>}</button>; }
function Icon({ name, size = 18, filled = false }: { name: IconName; size?: number; filled?: boolean }) { const paths: Record<IconName, React.ReactNode> = { home: <><path d="m4 10 8-6 8 6"/><path d="M6 9v10h12V9M10 19v-6h4v6"/></>, pulse: <path d="M3 12h4l2.2-6 4.1 12 2.2-6H21"/>, wallet: <><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M15 10h6v4h-6a2 2 0 0 1 0-4Z"/></>, star: <path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9L12 3z"/>, search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>, arrow: <><path d="M5 12h14"/><path d="m14 7 5 5-5 5"/></>, refresh: <><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 9a7 7 0 0 1 11.4-2L20 9M4 15l2.5 2a7 7 0 0 0 11.4-2"/></>, shield: <><path d="M12 3 5 6v5c0 4.6 2.8 8 7 10 4.2-2 7-5.4 7-10V6l-7-3Z"/><path d="M9 12h6M12 9v6"/></>, settings: <><circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0ZM12 2v3M12 19v3M2 12h3M19 12h3"/></>, copy: <><rect x="8" y="8" width="11" height="11" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></>, download: <><path d="M12 3v12m-4-4 4 4 4-4"/><path d="M4 19h16"/></>, filter: <path d="M4 6h16M7 12h10M10 18h4"/>, close: <path d="m6 6 12 12M18 6 6 18"/>, command: <><rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 9h8M8 13h5"/></>, eye: <><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></> }; return <svg aria-hidden="true" width={size} height={size} viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">{paths[name]}</svg>; }
